/* ==UserStyle==
@name           MEGPT – Chaos AI Theme
@namespace      megpt
@version        1.0
@description    MEGPT-style glitchy dark neon theme for ChatGPT
@match          https://chat.openai.com/*
==/UserStyle== */

:root {
  --megpt-bg: #0b0b14;
  --megpt-panel: #12122a;
  --megpt-text: #00ffcc;
  --megpt-accent: #ff00ff;
  --megpt-error: #ff3c3c;
  --megpt-border: #2d2d6e;
  --megpt-font: monospace;
}

/* Background */
body {
  background: var(--megpt-bg) !important;
  color: var(--megpt-text) !important;
  font-family: var(--megpt-font) !important;
}

/* Chat area */
main, section {
  background: var(--megpt-bg) !important;
}

/* Messages */
div[data-message-author-role="assistant"],
div[data-message-author-role="user"] {
  background: var(--megpt-panel) !important;
  border: 1px solid var(--megpt-border) !important;
  border-radius: 12px !important;
  margin: 8px 0 !important;
  box-shadow: 0 0 12px rgba(255,0,255,0.15);
}

/* Assistant text */
div[data-message-author-role="assistant"] {
  color: var(--megpt-text) !important;
}

/* User text */
div[data-message-author-role="user"] {
  color: white !important;
  border-left: 4px solid var(--megpt-accent) !important;
}

/* Input box */
textarea {
  background: #000 !important;
  color: var(--megpt-text) !important;
  border: 2px solid var(--megpt-accent) !important;
  border-radius: 10px !important;
}

/* Buttons */
button {
  background: transparent !important;
  border: 1px solid var(--megpt-accent) !important;
  color: var(--megpt-accent) !important;
  font-family: monospace !important;
}

button:hover {
  background: var(--megpt-accent) !important;
  color: black !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-thumb {
  background: var(--megpt-accent);
  border-radius: 10px;
}

/* Glitch header vibe */
h1, h2, h3 {
  text-shadow:
    2px 0 var(--megpt-accent),
    -2px 0 var(--megpt-error);
}

/* ERROR MODE (optional toggle later) */
